import numpy as np
from scipy.optimize import minimize

def _get_lhs():
    try:
        from pyDOE2 import lhs as _lhs
        def lhs(n_samples, n_dim): return _lhs(n_samples, n_dim)
    except ImportError:
        try:
            from scipy.stats import qmc
            def lhs(n_samples, n_dim):
                return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
        except ImportError:
            raise ImportError("pyDOE2 or scipy required")
    return lhs

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.cat_regions = []
        self._lhs = _get_lhs()
        self.stagnation_counter = 0
        self.last_best_f = float('inf')
        self.max_stagnation = 15
        self.cliff_history = []

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.asarray(x, dtype=np.float64)
        x = np.clip(x, -1.0, 1.0)
        try:
            f = func(x)
        except Exception:
            f = float('inf')
        if not np.isfinite(f):
            f = float('inf')
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
            self.stagnation_counter = 0
            self.last_best_f = f
            self.cliff_history = []
        else:
            self.stagnation_counter += 1
            if np.isinf(f):
                self.cliff_history.append(self.evals)
        return f

    def _stratified_cat_sample(self, n):
        use_clusters = len(self.cat_regions) > 2 and self.rng.random() < 0.65
        if use_clusters:
            idx = self.rng.integers(len(self.cat_regions))
            center, radius = self.cat_regions[idx]
            samples = center + self.rng.normal(0, radius * 0.4, (n, 6))
            if self.rng.random() < 0.3:
                idx2 = self.rng.integers(len(self.cat_regions))
                center2, radius2 = self.cat_regions[idx2]
                samples[self.rng.integers(n)] = center2 + self.rng.normal(0, radius2 * 0.2, (1, 6))
            return np.clip(samples, -1.0, 1.0)
        return self.rng.uniform(-1.0, 1.0, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(15, min(50, self.budget // 2))
        pop = self._lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._stratified_cat_sample(n_pop)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(6, min(25, self.budget // n_pop))
        f_div_history = []
        grad_norm_history = []
        local_search_budget = 0

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            valid_mask = np.isfinite(fitness)
            if not np.any(valid_mask):
                pop = self._lhs(n_samples=n_pop, n_dim=24)
                pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
                pop[:, 18:] = self._stratified_cat_sample(n_pop)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                self.stagnation_counter = 0
                continue

            valid_fit = fitness[valid_mask]
            f_mean, f_std = np.mean(valid_fit), np.std(valid_fit)
            f_div = f_std / (np.abs(f_mean) + 1e-9)
            f_div_history.append(f_div)
            if len(f_div_history) > 10: f_div_history.pop(0)
            current_div = np.mean(f_div_history)

            if self.stagnation_counter > self.max_stagnation or current_div < 0.06:
                n_reinit = max(5, n_pop // 3)
                idxs = self.rng.choice(n_pop, n_reinit, replace=False)
                for idx in idxs:
                    pop[idx] = self._lhs(1, 24)[0]
                    pop[idx] = np.clip(pop[idx] * 2.0 - 1.0, -1.0, 1.0)
                    pop[idx, 18:] = self._stratified_cat_sample(1)[0]
                    fitness[idx] = self._evaluate(pop[idx], func)
                self.stagnation_counter = 0
                f_div_history = []

            # Ensemble Gradient Guidance (Top 20%)
            grad_dir = None
            grad_norm = 0.0
            top_k = max(1, int(n_pop * 0.2))
            if grad_func:
                try:
                    valid_indices = np.where(valid_mask)[0]
                    top_indices = valid_indices[np.argsort(fitness[valid_indices])[:top_k]]
                    grad_accum = np.zeros(18)
                    for idx in top_indices:
                        g = grad_func(pop[idx])
                        if g is not None and len(g) == 18:
                            grad_accum += np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                    if np.any(grad_accum):
                        grad_accum /= len(top_indices)
                        grad_norm = np.linalg.norm(grad_accum)
                        if grad_norm > 1e-12:
                            grad_dir = grad_accum / grad_norm
                            grad_norm_history.append(grad_norm)
                            if len(grad_norm_history) > 8: grad_norm_history.pop(0)
                except Exception: pass

            # Adaptive Mutation Parameters
            base_F = 0.4 + 0.6 * (1.0 - current_div)
            recent_cliffs = len([t for t in self.cliff_history if self.evals - t < 5])
            F = np.clip(base_F + 0.35 * recent_cliffs, 0.4, 1.3)
            CR = np.clip(0.5 + 0.3 * current_div, 0.5, 0.9)

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            is_best_valid = np.isfinite(fitness[best_idx])

            alpha_grad = 0.0
            if grad_dir is not None and is_best_valid and len(grad_norm_history) > 0:
                imp = max(0.0, self.last_best_f - self.best_f)
                avg_g = np.mean(grad_norm_history)
                alpha_grad = np.clip(imp * 3.0 / (avg_g + 1e-9), 0.0, 0.3)

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while len(set(idxs).intersection({i})) > 0:
                    idxs = self.rng.choice(n_pop, 3, replace=False)

                v = x_best.copy()
                diff = pop[idxs[1]] - pop[idxs[2]]
                mut_scale = F * (1.0 + self.rng.standard_normal() * 0.08)
                v[:18] += mut_scale * diff[:18]
                v[18:] += mut_scale * diff[18:]

                if grad_dir is not None and is_best_valid:
                    v[:18] += alpha_grad * grad_dir

                v = np.clip(v, -1.0, 1.0)
                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, v, pop[i])
                trial = np.clip(trial, -1.0, 1.0)

                f_trial = self._evaluate(trial, func)

                # Cliff-reactive recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    step_size = 0.25 * (1.0 - self.evals/self.budget) + 0.05
                    x_expl = x_best.copy()
                    if grad_dir is not None:
                        x_expl[:18] -= step_size * grad_dir
                    else:
                        x_expl[:18] += step_size * self.rng.normal(0, 1, 18)
                    x_expl = np.clip(x_expl, -1.0, 1.0)
                    f_expl = self._evaluate(x_expl, func)
                    if np.isfinite(f_expl) and f_expl < self.best_f * 1.1:
                        trial = x_expl
                        f_trial = f_expl
                    else:
                        trial = self._lhs(1, 24)[0]
                        trial = np.clip(trial * 2.0 - 1.0, -1.0, 1.0)
                        trial[18:] = self._stratified_cat_sample(1)[0]
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        center = trial[18:]
                        if self.cat_regions:
                            dists = [np.linalg.norm(c - center) for c, _ in self.cat_regions]
                            min_idx = np.argmin(dists)
                            if dists[min_idx] < 0.3:
                                c, r = self.cat_regions[min_idx]
                                self.cat_regions[min_idx] = (0.9*c + 0.1*center, r*0.95)
                            else:
                                self.cat_regions.append((center.copy(), 0.2))
                        else:
                            self.cat_regions.append((center.copy(), 0.2))
                        if len(self.cat_regions) > 10: self.cat_regions.pop(0)

            # Budget-Aware Local Search Trigger
            local_budget_alloc = int((self.budget - self.evals) * 0.15)
            if local_budget_alloc > 10 and current_div < 0.12 and grad_func:
                top_indices = np.argsort(fitness)[:min(2, np.sum(valid_mask))]
                for idx in top_indices:
                    if self.evals >= self.budget or local_search_budget >= local_budget_alloc: break
                    if not np.isfinite(fitness[idx]): continue

                    x0_c, x0_cat = pop[idx][:18].copy(), pop[idx][18:].copy()
                    alloc = max(5, min(20, local_budget_alloc - local_search_budget))

                    def cost_wrap(x_c):
                        if self.evals >= self.budget: return float('inf')
                        return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)
                    def grad_wrap(x_c):
                        if self.evals >= self.budget: return np.zeros(18)
                        x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                        try:
                            g = grad_func(x_full)
                            return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                        except Exception: return np.zeros(18)

                    try:
                        res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                       bounds=[(-1.0, 1.0)]*18,
                                       options={'maxfun': alloc, 'ftol': 1e-10, 'gtol': 1e-10})
                        if np.isfinite(res.fun) and res.fun < fitness[idx]:
                            pop[idx] = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                            fitness[idx] = res.fun
                            local_search_budget += alloc
                            if res.fun < self.best_f:
                                self.best_f = res.fun
                                self.best_x = pop[idx].copy()
                    except Exception: pass

        if self.evals < self.budget * 0.95 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                x0 = pop[best_idx]
                x0_c, x0_cat = x0[:18].copy(), x0[18:].copy()
                def cost_wrap(x_c):
                    if self.evals >= self.budget: return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)
                def grad_wrap(x_c):
                    if self.evals >= self.budget: return np.zeros(18)
                    x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                    try:
                        g = grad_func(x_full)
                        return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)
                rem = max(10, min(40, int((self.budget - self.evals) * 0.2)))
                try:
                    res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)]*18,
                                   options={'maxfun': rem, 'ftol': 1e-12, 'gtol': 1e-10})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                except Exception: pass

        return self.best_f, self.best_x
